export const messages = { ar, en } as const;
export type Language = keyof typeof messages;
export type TranslationKey = keyof typeof ar;
export type Theme = 'light' | 'dark';

export const serviceTranslations: Record<Language, Record<string, { title: string; summary: string; businessValue: string; includes: string[]; deliverables: string[]; suitableFor: string }>> = {
  ar: Object.fromEntries(Array.from({ length: 6 }, (_, index) => { const id = String(index + 1); return [id, { title: ar[`service.${id}.title` as TranslationKey], summary: ar[`service.${id}.summary` as TranslationKey], businessValue: ar[`service.${id}.value` as TranslationKey], includes: ar[`service.${id}.include` as TranslationKey].split('|'), deliverables: ar[`service.${id}.deliver` as TranslationKey].split('|'), suitableFor: ar[`service.${id}.fit` as TranslationKey] }]; })),
  en: Object.fromEntries(Array.from({ length: 6 }, (_, index) => { const id = String(index + 1); return [id, { title: en[`service.${id}.title` as TranslationKey], summary: en[`service.${id}.summary` as TranslationKey], businessValue: en[`service.${id}.value` as TranslationKey], includes: en[`service.${id}.include` as TranslationKey].split('|'), deliverables: en[`service.${id}.deliver` as TranslationKey].split('|'), suitableFor: en[`service.${id}.fit` as TranslationKey] }]; })),
};

export const projectTranslations: Record<Language, Record<string, { categoryLabel: string; tagline: string; overview: string; challenge: string; solution: string; designApproach: string; features: string[]; developmentHighlights: string[] }>> = {
  ar: Object.fromEntries(['syrian-menu', 'pet-corner', 'mashwarak'].map((slug) => [slug, { categoryLabel: ar[`project.${slug}.category` as TranslationKey], tagline: ar[`project.${slug}.tagline` as TranslationKey], overview: ar[`project.${slug}.overview` as TranslationKey], challenge: ar[`project.${slug}.challenge` as TranslationKey], solution: ar[`project.${slug}.solution` as TranslationKey], designApproach: ar[`project.${slug}.approach` as TranslationKey], features: ar[`project.${slug}.features` as TranslationKey].split('|'), developmentHighlights: ar[`project.${slug}.highlights` as TranslationKey].split('|') }])),
  en: Object.fromEntries(['syrian-menu', 'pet-corner', 'mashwarak'].map((slug) => [slug, { categoryLabel: en[`project.${slug}.category` as TranslationKey], tagline: en[`project.${slug}.tagline` as TranslationKey], overview: en[`project.${slug}.overview` as TranslationKey], challenge: en[`project.${slug}.challenge` as TranslationKey], solution: en[`project.${slug}.solution` as TranslationKey], designApproach: en[`project.${slug}.approach` as TranslationKey], features: en[`project.${slug}.features` as TranslationKey].split('|'), developmentHighlights: en[`project.${slug}.highlights` as TranslationKey].split('|') }])),
};

export const challengeTranslations: Record<Language, Array<{ problem: string; solution: string }>> = {
  ar: Array.from({ length: 6 }, (_, index) => ({ problem: ar[`challenge.${index + 1}.problem` as TranslationKey], solution: ar[`challenge.${index + 1}.solution` as TranslationKey] })),
  en: Array.from({ length: 6 }, (_, index) => ({ problem: en[`challenge.${index + 1}.problem` as TranslationKey], solution: en[`challenge.${index + 1}.solution` as TranslationKey] })),
};
